'use client';

import { useEffect, useMemo, useRef } from 'react';
import * as THREE from 'three';
import { useGLTF, useTexture } from '@react-three/drei';
import { useFrame } from '@react-three/fiber';
import { CLOCK_CANVAS } from '@/lib/constants';
import {
  getClockSequenceState,
  type ClockSequenceState,
} from '@/lib/cycleScreenState';
import { drawClockFace } from '@/lib/drawClockFace';
import { useScrollStore } from '@/stores/scrollStore';

const CLOCK_MODEL_URL = '/models/flip-clock/retro-flip-clock-download-original.glb?v=canonical-face-2';
const CLOCK_TEXTURE_ROOT = '/models/flip-clock/textures';
const FACE_MASK = {
  width: 0.9,
  height: 0.84,
  radius: 0.13,
} as const;
const CAVITY_PANEL = {
  width: 0.965,
  height: 0.62,
  radius: 0.17,
} as const;
const WINDOW_BACKING = {
  width: 0.965,
  height: 0.8,
  radius: 0.16,
} as const;

export interface ClockModelProps {
  reducedMotion?: boolean;
  sequenceOverride?: ClockSequenceState;
}

interface PreparedClockModel {
  object: THREE.Group;
  box: THREE.Box3;
  size: THREE.Vector3;
}

interface ClockTextureSet {
  diffuse: THREE.Texture;
  normal: THREE.Texture;
  roughness: THREE.Texture;
  metalness: THREE.Texture;
  transmission: THREE.Texture;
}

function createRoundedRectShape(width: number, height: number, radius: number) {
  const halfWidth = width * 0.5;
  const halfHeight = height * 0.5;
  const r = Math.min(radius, halfWidth, halfHeight);
  const shape = new THREE.Shape();

  shape.moveTo(-halfWidth + r, -halfHeight);
  shape.lineTo(halfWidth - r, -halfHeight);
  shape.absarc(halfWidth - r, -halfHeight + r, r, -Math.PI / 2, 0, false);
  shape.lineTo(halfWidth, halfHeight - r);
  shape.absarc(halfWidth - r, halfHeight - r, r, 0, Math.PI / 2, false);
  shape.lineTo(-halfWidth + r, halfHeight);
  shape.absarc(-halfWidth + r, halfHeight - r, r, Math.PI / 2, Math.PI, false);
  shape.lineTo(-halfWidth, -halfHeight + r);
  shape.absarc(-halfWidth + r, -halfHeight + r, r, Math.PI, Math.PI * 1.5, false);

  return shape;
}

function configureTexture(
  texture: THREE.Texture,
  {
    colorSpace = THREE.NoColorSpace,
  }: {
    colorSpace?: THREE.ColorSpace;
  } = {},
) {
  texture.flipY = false;
  texture.colorSpace = colorSpace;
  texture.wrapS = THREE.ClampToEdgeWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;
  texture.anisotropy = 8;
  texture.needsUpdate = true;
}

function prepareMaterial(
  material: THREE.Material,
  textures: ClockTextureSet,
) {
  const base = material.clone();
  const materialName = base.name.toLowerCase();

  if (
    base instanceof THREE.MeshStandardMaterial ||
    base instanceof THREE.MeshPhysicalMaterial
  ) {
    if (base.map) {
      base.map.colorSpace = THREE.SRGBColorSpace;
      base.map.needsUpdate = true;
    }

    if (base.emissiveMap) {
      base.emissiveMap.colorSpace = THREE.SRGBColorSpace;
      base.emissiveMap.needsUpdate = true;
    }

    if (materialName === 'clockplastic') {
      base.map = null;
      base.normalMap = textures.normal;
      base.roughnessMap = textures.roughness;
      base.metalnessMap = null;
      base.color = new THREE.Color('#f0e6cf');
      base.roughness = 0.78;
      base.metalness = 0.02;
      base.envMapIntensity = 0.26;
      base.normalScale.set(0.11, 0.11);
      if (base instanceof THREE.MeshPhysicalMaterial) {
        base.clearcoat = 0.18;
        base.clearcoatRoughness = 0.42;
      }
    }

    if (materialName === 'clockblack') {
      base.map = null;
      base.normalMap = textures.normal;
      base.roughnessMap = textures.roughness;
      base.metalnessMap = null;
      base.color = new THREE.Color('#050604');
      base.roughness = 0.96;
      base.metalness = 0.0;
      base.envMapIntensity = 0.04;
      base.normalScale.set(0.012, 0.012);
    }

    if (materialName === 'deskclockglass') {
      base.transparent = true;
      base.opacity = 0.12;
      base.color = new THREE.Color('#1a1a18');
      base.roughnessMap = textures.roughness;
      base.normalMap = textures.normal;
      base.roughness = 0.06;
      base.metalness = 0;
      if (base instanceof THREE.MeshPhysicalMaterial) {
        base.transmissionMap = null;
        base.transmission = 0.18;
        base.ior = 1.45;
        base.thickness = 0.014;
        base.envMapIntensity = 0.22;
        base.clearcoat = 0.12;
        base.clearcoatRoughness = 0.18;
      }
      base.normalScale.set(0.008, 0.008);
    }

    if (materialName === 'clockbackpanelmat') {
      base.color = new THREE.Color('#0f100c');
      base.roughness = 0.92;
      base.metalness = 0;
    }

    if (materialName === 'clockinnershadowmat') {
      base.color = new THREE.Color('#060704');
      base.roughness = 1;
      base.metalness = 0;
    }

    if (materialName === 'clocknumbers') {
      base.transparent = true;
      base.opacity = 0;
      base.color = new THREE.Color('#000000');
      base.roughness = 1;
      base.metalness = 0;
      base.envMapIntensity = 0;
      if (base instanceof THREE.MeshPhysicalMaterial) {
        base.transmission = 0;
        base.thickness = 0;
      }
    }
  }

  base.needsUpdate = true;
  return base;
}

function prepareClockModel(
  scene: THREE.Group,
  textures: ClockTextureSet,
): PreparedClockModel {
  const clone = scene.clone(true);

  clone.traverse((child) => {
    if (!(child instanceof THREE.Mesh)) return;

    child.castShadow = true;
    child.receiveShadow = true;
    child.frustumCulled = false;

    if (Array.isArray(child.material)) {
      child.material = child.material.map((material) =>
        prepareMaterial(material, textures),
      );
    } else {
      child.material = prepareMaterial(child.material, textures);
    }
  });

  clone.rotation.y = -Math.PI / 2;

  let box = new THREE.Box3().setFromObject(clone);
  const rawSize = box.getSize(new THREE.Vector3());
  const maxDimension = Math.max(rawSize.x, rawSize.y, rawSize.z) || 1;
  const scale = 2.58 / maxDimension;
  clone.scale.setScalar(scale);

  box = new THREE.Box3().setFromObject(clone);
  const center = box.getCenter(new THREE.Vector3());
  const size = box.getSize(new THREE.Vector3());

  clone.position.x -= center.x;
  clone.position.y -= center.y - size.y * 0.02;
  clone.position.z -= center.z;

  box = new THREE.Box3().setFromObject(clone);

  return {
    object: clone,
    box,
    size: box.getSize(new THREE.Vector3()),
  };
}

export default function ClockModel({
  reducedMotion = false,
  sequenceOverride,
}: ClockModelProps) {
  const gltf = useGLTF(CLOCK_MODEL_URL);
  const [
    diffuseMap,
    normalMap,
    roughnessMap,
    metalnessMap,
    transmissionMap,
  ] = useTexture([
    `${CLOCK_TEXTURE_ROOT}/FlipClock_Bake1_PBR_Diffuse.png`,
    `${CLOCK_TEXTURE_ROOT}/FlipClock_Bake1_PBR_Normal.png`,
    `${CLOCK_TEXTURE_ROOT}/FlipClock_Bake1_PBR_Roughness.png`,
    `${CLOCK_TEXTURE_ROOT}/FlipClock_Bake1_PBR_Metalness.png`,
    `${CLOCK_TEXTURE_ROOT}/FlipClock_Bake1_PBR_Transmission.png`,
  ]);
  const groupRef = useRef<THREE.Group>(null);
  const pulseRef = useRef<THREE.PointLight>(null);
  const faceMaterialRef = useRef<THREE.MeshBasicMaterial | null>(null);
  const ctxRef = useRef<CanvasRenderingContext2D | null>(null);
  const textureRef = useRef<THREE.CanvasTexture | null>(null);
  const lastStateKeyRef = useRef('');
  const shellTextures = useMemo(() => {
    configureTexture(diffuseMap, { colorSpace: THREE.SRGBColorSpace });
    configureTexture(normalMap);
    configureTexture(roughnessMap);
    configureTexture(metalnessMap);
    configureTexture(transmissionMap);

    return {
      diffuse: diffuseMap,
      normal: normalMap,
      roughness: roughnessMap,
      metalness: metalnessMap,
      transmission: transmissionMap,
    };
  }, [diffuseMap, metalnessMap, normalMap, roughnessMap, transmissionMap]);
  const preparedModel = useMemo(
    () => prepareClockModel(gltf.scene, shellTextures),
    [gltf.scene, shellTextures],
  );

  useEffect(() => {
    const canvas = document.createElement('canvas');
    canvas.width = CLOCK_CANVAS.width;
    canvas.height = CLOCK_CANVAS.height;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 4;
    texture.needsUpdate = true;

    ctxRef.current = ctx;
    textureRef.current = texture;
    lastStateKeyRef.current = '';

    if (faceMaterialRef.current) {
      faceMaterialRef.current.map = texture;
      faceMaterialRef.current.needsUpdate = true;
    }

    return () => {
      texture.dispose();
      ctxRef.current = null;
      textureRef.current = null;
      lastStateKeyRef.current = '';
    };
  }, []);

  const clockProgress = useScrollStore((state) => state.clockProgress);

  useFrame((state) => {
    const node = groupRef.current;
    if (!node) return;

    const liveClockState =
      sequenceOverride ?? getClockSequenceState(clockProgress, reducedMotion);
    const ctx = ctxRef.current;
    const texture = textureRef.current;
    const elapsed = state.clock.elapsedTime;
    const ring = liveClockState.ringAmount;
    const appear = 0.92 + liveClockState.displayProgress * 0.08;
    const faceKey = [
      liveClockState.displayProgress.toFixed(3),
      liveClockState.faceIn.toFixed(3),
      liveClockState.hold0659.toFixed(3),
      liveClockState.flipMinuteOnes.toFixed(3),
      liveClockState.flipMinuteTens.toFixed(3),
      liveClockState.flipHourOnes.toFixed(3),
      liveClockState.settle0700.toFixed(3),
      liveClockState.flashAmount.toFixed(3),
    ].join('|');

    if (ctx && texture && faceKey !== lastStateKeyRef.current) {
      drawClockFace(ctx, liveClockState);
      texture.needsUpdate = true;
      lastStateKeyRef.current = faceKey;
    }

    node.scale.setScalar(appear);
    node.rotation.y = reducedMotion
      ? 0.04
      : 0.08 + Math.sin(elapsed * 0.45) * 0.026;
    node.rotation.x = reducedMotion
      ? -0.03
      : -0.055 + Math.sin(elapsed * 0.22) * 0.012;
    node.rotation.z = ring * Math.sin(elapsed * 18) * (reducedMotion ? 0.003 : 0.009);
    node.position.y =
      -0.14 +
      (1 - liveClockState.displayProgress) * 0.08 +
      ring * Math.sin(elapsed * 14) * (reducedMotion ? 0.003 : 0.012);
    node.position.x = ring * Math.sin(elapsed * 16) * (reducedMotion ? 0.002 : 0.008);

    if (pulseRef.current) {
      pulseRef.current.intensity =
        0.08 + liveClockState.flashAmount * 0.32 + liveClockState.settle0700 * 0.06;
    }
  });

  const faceWidth = preparedModel.size.x * 0.82;
  const faceHeight = preparedModel.size.y * 0.44;
  const faceY = preparedModel.box.min.y + preparedModel.size.y * 0.56;
  const faceZ = preparedModel.box.max.z - preparedModel.size.z * 0.038;
  const windowWidth = preparedModel.size.x * 0.93;
  const windowHeight = preparedModel.size.y * 0.74;
  const windowRadius = windowHeight * WINDOW_BACKING.radius;
  const cavityWidth = preparedModel.size.x * 0.9;
  const cavityHeight = preparedModel.size.y * 0.52;
  const cavityRadius = cavityHeight * CAVITY_PANEL.radius;
  const windowShape = useMemo(
    () => createRoundedRectShape(windowWidth, windowHeight, windowRadius),
    [windowHeight, windowRadius, windowWidth],
  );
  const maskWidth = faceWidth * FACE_MASK.width;
  const maskHeight = faceHeight * FACE_MASK.height;
  const maskRadius = maskHeight * FACE_MASK.radius;
  const cavityShape = useMemo(
    () => createRoundedRectShape(cavityWidth, cavityHeight, cavityRadius),
    [cavityHeight, cavityRadius, cavityWidth],
  );
  const maskShape = useMemo(
    () => createRoundedRectShape(maskWidth, maskHeight, maskRadius),
    [maskHeight, maskRadius, maskWidth],
  );
  const windowZ = faceZ - preparedModel.size.z * 0.03;
  const cavityZ = faceZ - preparedModel.size.z * 0.024;
  const maskZ = faceZ + preparedModel.size.z * 0.0025;
  const lightY = preparedModel.box.min.y + preparedModel.size.y * 0.56;
  const lightZ = preparedModel.box.max.z + 0.76;

  return (
    <group ref={groupRef} position={[0, -0.14, 0]}>
      <primitive object={preparedModel.object} />
      <mesh position={[0, faceY, windowZ]} renderOrder={2}>
        <shapeGeometry args={[windowShape]} />
        <meshPhysicalMaterial
          color="#050604"
          transparent
          opacity={0.26}
          roughness={0.18}
          metalness={0}
          transmission={0.12}
          ior={1.22}
          thickness={0.01}
          envMapIntensity={0.08}
          toneMapped={false}
          depthWrite={false}
          depthTest={false}
        />
      </mesh>

      <mesh position={[0, faceY, maskZ]} renderOrder={3}>
        <shapeGeometry args={[maskShape]} />
        <meshBasicMaterial
          colorWrite={false}
          depthWrite={false}
          depthTest={false}
          transparent
          opacity={0}
          stencilWrite
          stencilRef={1}
          stencilFunc={THREE.AlwaysStencilFunc}
          stencilFail={THREE.ReplaceStencilOp}
          stencilZFail={THREE.ReplaceStencilOp}
          stencilZPass={THREE.ReplaceStencilOp}
        />
      </mesh>

      <mesh position={[0, faceY, cavityZ]} renderOrder={4}>
        <shapeGeometry args={[cavityShape]} />
        <meshBasicMaterial
          color="#060704"
          toneMapped={false}
          depthWrite={false}
          depthTest={false}
          polygonOffset
          polygonOffsetFactor={-1}
          polygonOffsetUnits={-1}
          stencilWrite
          stencilRef={1}
          stencilFunc={THREE.EqualStencilFunc}
          stencilFail={THREE.KeepStencilOp}
          stencilZFail={THREE.KeepStencilOp}
          stencilZPass={THREE.KeepStencilOp}
        />
      </mesh>

      <mesh position={[0, faceY, faceZ]} renderOrder={5}>
        <planeGeometry args={[faceWidth, faceHeight]} />
        <meshBasicMaterial
          ref={faceMaterialRef}
          toneMapped={false}
          side={THREE.DoubleSide}
          transparent
          depthWrite={false}
          depthTest={false}
          polygonOffset
          polygonOffsetFactor={-2}
          polygonOffsetUnits={-2}
          stencilWrite
          stencilRef={1}
          stencilFunc={THREE.EqualStencilFunc}
          stencilFail={THREE.KeepStencilOp}
          stencilZFail={THREE.KeepStencilOp}
          stencilZPass={THREE.KeepStencilOp}
        />
      </mesh>

      <pointLight
        ref={pulseRef}
        position={[0, lightY, lightZ]}
        color="#f2ddad"
        intensity={0.09}
        distance={3.3}
      />

      <spotLight
        position={[1.8, 1.3, 2.4]}
        angle={0.42}
        penumbra={0.8}
        intensity={0.24}
        distance={7}
        color="#ffe8bf"
      />
    </group>
  );
}

useGLTF.preload(CLOCK_MODEL_URL);
