'use client';

import { Suspense } from 'react';
import ClockModelPolish from './ClockModelPolish';
import SceneContainer from './SceneContainer';
import ClockModelRefined from './ClockModelRefined';
import ClockModelStable from './ClockModelStable';
import {
  ACTIVE_CLOCK_VARIANT,
  type ClockVariant,
} from './clockVariants';
import { StudioEnvironment } from '@/lib/createEnvMap';
import type { ClockSequenceState } from '@/lib/cycleScreenState';

const DEFAULT_CLOCK_DISPLAY_SCALE = 0.5;

interface ClockSceneProps {
  reducedMotion?: boolean;
  variant?: ClockVariant;
  sequenceOverride?: ClockSequenceState;
  modelYawOffset?: number;
  clockScale?: number;
}

export default function ClockScene({
  reducedMotion = false,
  variant = ACTIVE_CLOCK_VARIANT,
  sequenceOverride,
  modelYawOffset = 0,
  clockScale = DEFAULT_CLOCK_DISPLAY_SCALE,
}: ClockSceneProps) {
  const isPolish = variant === 'polish';
  const Model =
    variant === 'stable'
      ? ClockModelStable
      : variant === 'polish'
        ? ClockModelPolish
        : ClockModelRefined;

  return (
    <SceneContainer
      camera={{ fov: 30, near: 0.01, far: 40, position: [0, 0.12, 5.05] }}
      toneMappingExposure={0.98}
    >
      <ambientLight
        intensity={isPolish ? 0.14 : 0.18}
        color={isPolish ? '#ead8bc' : '#eadcc1'}
      />
      <directionalLight
        position={isPolish ? [2.22, 2.84, 5.16] : [2.4, 2.9, 5.4]}
        intensity={isPolish ? 1.04 : 1.18}
        color={isPolish ? '#fff1d5' : '#fff1d7'}
      />
      <directionalLight
        position={isPolish ? [-1.28, 1.08, 4.28] : [-1.65, 0.95, 4.65]}
        intensity={isPolish ? 0.24 : 0.17}
        color={isPolish ? '#fff6df' : '#fff7e3'}
      />
      <directionalLight
        position={[-3.4, 1.1, 2.1]}
        intensity={isPolish ? 0.05 : 0.08}
        color={isPolish ? '#c7b27f' : '#d2bd90'}
      />
      <directionalLight
        position={[1.2, 2.6, -4.8]}
        intensity={isPolish ? 0.08 : 0.12}
        color="#fff9eb"
      />
      {isPolish ? (
        <directionalLight
          position={[0.3, 2.28, 3.18]}
          intensity={0.14}
          color="#fff0ca"
        />
      ) : null}
      <pointLight
        position={isPolish ? [0.06, 0.46, 2.04] : [0.08, 0.5, 2.2]}
        intensity={isPolish ? 0.018 : 0.03}
        color="#e9d19a"
        distance={6.8}
      />
      <StudioEnvironment />
      <Suspense fallback={null}>
        <group
          rotation={[0, modelYawOffset, 0]}
          scale={[clockScale, clockScale, clockScale]}
        >
          <Model
            reducedMotion={reducedMotion}
            sequenceOverride={sequenceOverride}
          />
        </group>
      </Suspense>
    </SceneContainer>
  );
}
